import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.Cu3jFwFD.js";const u=JSON.parse('{"title":"Packages","description":"","frontmatter":{},"headers":[],"relativePath":"features/packages/design.md","filePath":"features/packages/design.md","lastUpdated":1794907319000}'),i={name:"features/packages/design.md"};function d(o,e,n,l,h,c){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h1><p><strong>Status:</strong> <span class="status-badge status-designed">DESIGNED</span> · <strong>Updated:</strong> 2026-11-17 · <a href="./../../GDD">GDD</a></p><p>Packages appear at pickup markers around the map (the Crazy Taxi model). The player drives into a marker, presses E, drives to the destination and presses E again. Money is paid on delivery. There are three kinds: Safe for steady money, Zeus&#39;s god package for a blessing that leaves with the package, and Chance (smuggled, &quot;scam&quot;) for a visible gamble. Serves <strong>Push your luck</strong> and <strong>Whimsical &amp; comedic</strong>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ol><li><strong>Interact (E):</strong> pressing E while the van is inside a marker&#39;s zone picks the package up (pickup marker) or delivers it (destination marker). The van does <strong>not</strong> need to slow down or stop: the game is fast-paced (<a class="decision-ref" href="/hex-gdd/GDD#d-060">D‑060</a>). Leniency: the zone counts 1 m wider than drawn, a press up to 0.4 s after leaving the zone still counts, and a press up to 0.3 s before entering is buffered and fires on arrival.</li><li><strong>One package per press</strong> (<a class="decision-ref" href="/hex-gdd/GDD#d-076">D‑076</a>): each E press picks up or delivers exactly one package. When several are in reach (markers close together, or several carried packages for the same stop), the player presses E once per package. Order when more than one is possible: deliver before pick up; among deliveries, the one carried longest first; among pickups, the nearest marker first <mark class="tune">TUNE</mark>. The interact leniency (rule 1) applies to every press, and a press buffered while a scam reveal plays fires after it ends.</li><li>Money is paid on delivery, never on pickup.</li><li><strong>Cargo is unlimited</strong> (<a class="decision-ref" href="/hex-gdd/GDD#d-028">D‑028</a>): no slot limit, no weight.</li><li><strong>Spawning:</strong> the map keeps a target number of open pickups (set by the trial&#39;s intensity, see <a href="./../trials/design">trials</a>) and adds one new job every spawn interval while below the target. At least one open pickup is always within 60 m of the van <mark class="tune">TUNE</mark>. No new jobs are added once 15 s or less of the shift are left.</li><li><strong>Mix</strong> (<a class="decision-ref" href="/hex-gdd/GDD#d-059">D‑059</a>): each new job is Chance with 25% chance from Day 2 on (0% on Day 1), otherwise Safe. Zeus is not part of the random mix: exactly one Zeus job spawns per normal day, on Day 1 at the start of the shift and on Day 2–3 at a random time between 10 s and 30 s into the shift <mark class="tune">TUNE</mark>. At most one Zeus job exists at a time.</li><li><strong>Routes:</strong> a pickup is placed 15–110 m from the van; its destination is 60–250 m from the pickup and at least 45 m from HQ <mark class="tune">TUNE: prototype values; re-measure on the new city map</mark>.</li><li><strong>Marker</strong> (<a class="decision-ref" href="/hex-gdd/GDD#d-075">D‑075</a>): every pickup shows a box icon for its type (Safe: blue box with the Hermes Express logo; Chance: red box with a devil; Zeus: gold box with a crown) and 1–3 coins above it for its pay level. The failure chance of a Chance package is <strong>not</strong> shown, neither as skulls nor as a percentage: players in testing read only the money. A carried package shows an arrow to its destination. <code>coins = 1 if basePay &lt; 1.5 × safeAvg else 2 if basePay &lt; 5 × safeAvg else 3</code>, where <code>safeAvg</code> is the middle of the Safe base pay range (14.5).</li><li><strong>Safe:</strong> pays a random whole amount from the Safe pay range.</li><li><strong>Zeus (god package, Offering):</strong> pickup at Zeus&#39;s palace, destination the Electrical Plant. From pickup, the van has the <strong>Zeus ward</strong>: lightning that would hit it is turned away (golden aura, RESIST pop-up). The ward ends on delivery or after the ward duration, whichever comes first. <em>The blessing belonged to the package, not you.</em></li><li><strong>Chance (scam):</strong> on spawn each Chance job gets a tier (1, 2 or 3, equally likely <mark class="tune">TUNE</mark>) with its failure chance (<a class="decision-ref" href="/hex-gdd/GDD#d-034">D‑034</a>) and its pay: <code>chancePay = round(rollSafePay() × tierMultiplier)</code> (<a class="decision-ref" href="/hex-gdd/GDD#d-061">D‑061</a>). At delivery roll once: success pays; failure pays nothing, costs the van 2 HP (<a class="decision-ref" href="/hex-gdd/GDD#d-035">D‑035</a>) and throws it into the air as feedback. A slot-machine reveal plays either way.</li><li><strong>Pay formula</strong> for every delivery, rounded to whole dollars once at the end: <code>paid = round(base × globalPayMultiplier × trialValueMultiplier × upgradePayMultiplier × (inOvertime ? overtimePayMultiplier : 1))</code>, where <code>base</code> is the Safe roll, the Zeus roll or the Chance pay above.</li><li>Only Zeus&#39;s package exists as a god package in the MVP; other gods are later.</li><li>Carried and open packages disappear when the day ends; there is no fine (<a class="decision-ref" href="/hex-gdd/GDD#d-045">D‑045</a>).</li></ol><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Value</th><th>Unit</th><th>What to watch in playtests</th></tr></thead><tbody><tr><td>Safe package base pay</td><td>10–19, whole dollars</td><td>$</td><td>Income per minute vs the run quota</td></tr><tr><td>Zeus package base pay</td><td>20–34, about 2× Safe (<a class="decision-ref" href="/hex-gdd/GDD#d-036">D‑036</a>)</td><td>$</td><td>Worth the detour on the smaller city map</td></tr><tr><td>Chance (scam) package failure chance, tier 1 / 2 / 3 (hidden from the player, <a class="decision-ref" href="/hex-gdd/GDD#d-075">D‑075</a>)</td><td>10 / 25 / 50 (<a class="decision-ref" href="/hex-gdd/GDD#d-034">D‑034</a>)</td><td>%</td><td>Share of players who take each tier</td></tr><tr><td>Coin thresholds: 2 coins from / 3 coins from</td><td>1.5× / 5× the Safe average base pay <mark class="tune">TUNE</mark></td><td>×</td><td>Safe = 1 coin, Zeus and Chance tiers 1–2 = 2 coins, Chance tier 3 = 3 coins</td></tr><tr><td>Chance (scam) package pay multiplier on a Safe roll, tier 1 / 2 / 3</td><td>×2 / ×4 / ×9 (<a class="decision-ref" href="/hex-gdd/GDD#d-061">D‑061</a>) <mark class="tune">TUNE</mark></td><td>factor</td><td>Each tier&#39;s expected value should sit a little above a Safe job</td></tr><tr><td>Chance (scam) package share of new jobs, Day 2–3</td><td>25 (<a class="decision-ref" href="/hex-gdd/GDD#d-059">D‑059</a>) <mark class="tune">TUNE</mark></td><td>%</td><td></td></tr><tr><td>Zeus jobs per normal day</td><td>1 (<a class="decision-ref" href="/hex-gdd/GDD#d-059">D‑059</a>)</td><td>jobs</td><td></td></tr><tr><td>Zeus job spawn time, Day 2–3</td><td>10–30 s into the shift <mark class="tune">TUNE</mark></td><td>s</td><td></td></tr><tr><td>Global pay multiplier</td><td>0.65 <mark class="tune">TUNE</mark></td><td>factor</td><td>Single dial for the whole economy</td></tr><tr><td>Open pickups on the map / new job interval</td><td>set by trial intensity, see <a href="./../trials/design">trials</a></td><td>jobs / s</td><td></td></tr><tr><td>Nearest open pickup, max distance from the van</td><td>60 <mark class="tune">TUNE</mark></td><td>m</td><td></td></tr><tr><td>No new jobs in the last</td><td>15</td><td>s of shift</td><td></td></tr><tr><td>Zeus ward duration</td><td>30</td><td>s</td><td>Long enough for the plant run, short enough to matter</td></tr><tr><td>Failed Chance (scam) delivery damage</td><td>2 (<a class="decision-ref" href="/hex-gdd/GDD#d-035">D‑035</a>)</td><td>HP</td><td>Same as a lightning strike</td></tr><tr><td>Interact leniency: zone padding / after leaving / before entering</td><td>1 / 0.4 / 0.3</td><td>m / s / s</td><td>Missed E presses at full speed</td></tr></tbody></table><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><ul><li>A failed Chance delivery can wreck the van when HP is 2 or less (<a class="decision-ref" href="/hex-gdd/GDD#d-037">D‑037</a>).</li><li>A failed Chance delivery in overtime pays nothing; overtime money already earned is lost if the wreck follows.</li><li>The Zeus ward does not stop Chance (scam) damage.</li><li>Pressing E at full speed through a marker counts; overshooting by up to 0.4 s still counts.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li>Why ×2 / ×4 / ×9: with −2 HP (about $60 of repair) on failure, each tier&#39;s expected value is just above a Safe job at these multipliers (tier 1 ≥ 1.9×, tier 2 ≥ 3.6×, tier 3 ≥ 8.7×).</li><li>With unlimited cargo the old &quot;Zeus costs 2 slots&quot; price is gone; check in playtests whether picking up Zeus is still a real decision.</li><li>The Day 1 tutorial (two Safe packages, then Zeus, scripted strikes) is a later feature (<a href="./../../GDD#feature-index">GDD</a>).</li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li>2026-11-17: designed. <a class="decision-ref" href="/hex-gdd/GDD#d-028">D‑028</a> (unlimited cargo) supersedes the 3-slot capacity and Zeus&#39;s 2 slots (<a class="decision-ref" href="/hex-gdd/GDD#d-020">D‑020</a>); <a class="decision-ref" href="/hex-gdd/GDD#d-027">D‑027</a> restores the intent of <a class="decision-ref" href="/hex-gdd/GDD#d-017">D‑017</a>.</li><li>2026-11-17: one package per E press (<a class="decision-ref" href="/hex-gdd/GDD#d-076">D‑076</a>).</li><li>2026-11-17: marker shows type box + coins only; failure chance hidden after user testing (<a class="decision-ref" href="/hex-gdd/GDD#d-075">D‑075</a>).</li><li>2026-11-17: made implementable: interact without stopping (<a class="decision-ref" href="/hex-gdd/GDD#d-060">D‑060</a>), job mix and Zeus once per day (<a class="decision-ref" href="/hex-gdd/GDD#d-059">D‑059</a>), Chance pay formula (<a class="decision-ref" href="/hex-gdd/GDD#d-061">D‑061</a>), full pay formula, route distances.</li></ul>',13)])])}const f=a(i,[["render",d]]);export{u as __pageData,f as default};
